import os
import subprocess
import tempfile
import pytest

# ── Pre-computed test vectors ──────────────────────────────────────────────
# Each tuple: (name, expected_output_hex, compressed_input_hex)
# Generated with: lz4.block.compress(data, store_size=False)

TEST_VECTORS = [
    # Empty input: single 0x00 byte
    ("empty", "", "00"),

    # Very short (all literals): "Hi"
    ("very_short", "4869", "204869"),

    # Simple text: 53 bytes
    ("simple_text",
     "48656c6c6f2c20576f726c6421205468697320697320612074657374206f6620746865204c5a34206465636f6d70726573736f722e",
     "f02648656c6c6f2c20576f726c6421205468697320697320612074657374206f6620746865204c5a34206465636f6d70726573736f722e"),

    # Single byte repeated 500 times (tests offset=1 overlapping copy)
    ("single_byte_repeat_500",
     "41" * 500,
     "1f410100ffdc504141414141"),

    # Four-byte pattern "ABCD" repeated 250 times (tests overlapping copy)
    ("four_byte_repeat",
     "41424344" * 250,
     "4f414243440400ffffffcf504441424344"),

    # Random 5KB (incompressible, mostly literals)
    ("random_5k",
     "",
     ""),

    # Text with repeated phrases (tests medium-length matches)
    ("text_runs",
     "54686520717569636b2062726f776e20666f782e20" * 50,
     "ff0654686520717569636b2062726f776e20666f782e201500fffffff050666f782e20"),

    # Binary pattern (sequential bytes 0..63 repeated, tests multi-byte length)
    ("binary_pattern",
     "000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f202122232425262728292a2b2c2d2e2f303132333435363738393a3b3c3d3e3f" * 31 + "000102030405060708090a0b0c0d0e0f",
     "ff31000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f202122232425262728292a2b2c2d2e2f303132333435363738393a3b3c3d3e3f4000ffffffffffffff7f500b0c0d0e0f"),

    # Multi-byte length encoding (0..255 repeated 10x, 2560 bytes)
    ("multi_byte_lengths",
     "" * 10,
     ""),

    # Mixed patterns (AAAA BBBB*10 CCCC*20 DDDD)
    ("mixed_patterns",
     "41414141" + "42424242" * 10 + "43434343" * 20 + "44444444",
     "5f41414141420100141f4301003b504344444444"),
]


# ── Corrupt / edge test vectors ──────────────────────────────────────────
# Each also paired with a "sanity" valid vector - the test first verifies
# that the decompressor works on valid data, then checks corrupt rejection.
# This ensures the test FAILS in the initial unimplemented state.

CORRUPT_VECTORS = [
    # Offset = 0 (invalid per spec, must be rejected)
    ("offset_zero", "1f41000000"),
    # Truncated input: token says 10 literals but only 3 bytes follow
    ("truncated_literals", "a0414241"),
    # Truncated input: token + 1 literal, match_nibble=15, but input
    # ends right after the offset (no room for match extra bytes)
    ("truncated_no_match_extra", "1f410100"),
]

# Known-good simple vector used as a sanity check before corrupt tests
SANITY_VECTOR = ("simple_text",
    "48656c6c6f2c20576f726c6421205468697320697320612074657374206f6620746865204c5a34206465636f6d70726573736f722e",
    "f02648656c6c6f2c20576f726c6421205468697320697320612074657374206f6620746865204c5a34206465636f6d70726573736f722e")


# ── Compilation helper ───────────────────────────────────────────────────

def _compile_decompressor():
    """Compile the solver's lz4_decompress.c and test_runner.c."""
    app_dir = "/app"

    # Build the decompressor library
    result = subprocess.run(
        ["make", "-C", app_dir, "clean"],
        capture_output=True, text=True, timeout=30
    )
    result = subprocess.run(
        ["make", "-C", app_dir, "liblz4dec.a"],
        capture_output=True, text=True, timeout=30
    )
    if result.returncode != 0:
        raise RuntimeError(f"Compilation of lz4_decompress.c failed:\n{result.stderr}")

    # Build test runner
    result = subprocess.run(
        ["make", "-C", app_dir, "test_runner"],
        capture_output=True, text=True, timeout=30
    )
    if result.returncode != 0:
        raise RuntimeError(f"Compilation of test_runner failed:\n{result.stderr}")


def _run_decompress(compressed_hex: str) -> bytes:
    """Run the decompressor on the given compressed data, return output."""
    compressed = bytes.fromhex(compressed_hex)
    result = subprocess.run(
        ["/app/test_runner"],
        input=compressed,
        capture_output=True, timeout=10
    )
    if result.returncode != 0:
        return None  # Decompression error
    return result.stdout


# ── Tests ─────────────────────────────────────────────────────────────────

def test_decompressor_compiles_and_works():
    """Verify the solver's code compiles AND produces correct output for basic input."""
    _compile_decompressor()

    # Must decompress a trivial block correctly to prove implementation works
    # "Hi" -> compressed as all-literals: token=0x20 (2 literals, no match),
    # followed by "Hi" bytes
    output = _run_decompress("204869")
    assert output is not None, (
        "Decompressor returned error for trivial valid input 'Hi'"
    )
    assert output == b"Hi", (
        f"Trivial decompression failed: expected b'Hi', got {output}"
    )


@pytest.mark.parametrize("name,expected_hex,compressed_hex", TEST_VECTORS)
def test_decompress_valid(name, expected_hex, compressed_hex):
    """Test decompression of valid LZ4 blocks against expected output."""
    _compile_decompressor()
    expected = bytes.fromhex(expected_hex)
    output = _run_decompress(compressed_hex)
    assert output is not None, (
        f"[{name}] Decompression failed (returned error) for valid input"
    )
    assert output == expected, (
        f"[{name}] Decompressed output mismatch.\n"
        f"Expected {len(expected)} bytes, got {len(output)} bytes.\n"
        f"First differing at byte: "
        f"{next((i for i, (a, b) in enumerate(zip(expected, output)) if a != b), 'unknown')}"
    )


def test_decompress_rejects_corrupt():
    """Test that corrupt/invalid LZ4 blocks are properly rejected.

    First verifies the decompressor works on valid data (fail-fast guard),
    then checks each corrupt vector is rejected.
    """
    _compile_decompressor()

    # Sanity: must be able to decompress valid data first
    name, expected_hex, compressed_hex = SANITY_VECTOR
    expected = bytes.fromhex(expected_hex)
    output = _run_decompress(compressed_hex)
    assert output is not None, (
        f"Sanity check failed: cannot decompress valid '{name}' block. "
        f"Fix valid decompression before corrupt rejection can be tested."
    )
    assert output == expected, (
        f"Sanity check failed: valid '{name}' block decompressed incorrectly."
    )

    # Now test corrupt vectors
    for name, compressed_hex in CORRUPT_VECTORS:
        output = _run_decompress(compressed_hex)
        assert output is None, (
            f"[{name}] Decompressor should have rejected corrupt input "
            f"but returned {len(output) if output else 0} bytes instead"
        )


def test_decompress_edge_cases():
    """Test edge cases: empty input, empty block, overlapping matches."""
    _compile_decompressor()

    # Empty LZ4 block (single 0x00 byte) -> empty output
    output = _run_decompress("00")
    assert output is not None, (
        "Decompressor should accept empty block (0x00 byte)"
    )
    assert output == b"", (
        f"Empty block should decompress to empty, got {len(output)} bytes"
    )

    # Completely empty input (0 bytes) should fail
    output = _run_decompress("")
    assert output is None, (
        "Decompressor should reject completely empty input (0 bytes)"
    )

    # Overlapping match: single byte repeated 500 times (offset=1)
    expected = bytes.fromhex("41" * 500)
    output = _run_decompress("1f410100ffdc504141414141")
    assert output is not None, (
        "Decompression failed for overlapping match (offset=1, 500 'A's)"
    )
    assert output == expected, (
        "Overlapping match output mismatch for 500 'A's"
    )

    # Overlapping match: four-byte pattern "ABCD" repeated 250 times
    expected = bytes.fromhex("41424344" * 250)
    output = _run_decompress("4f414243440400ffffffcf504441424344")
    assert output is not None, (
        "Decompression failed for overlapping match (offset=4, 'ABCD' x 250)"
    )
    assert output == expected, (
        "Overlapping match output mismatch for 'ABCD' x 250"
    )

